def _hill_lagrange(qv, wrong="none"):
    """the r306 leg-A exact chain on a rational probability vector:
    the two Lagrange witnesses (dev1/dev2 must be 0), the power-mean
    slacks S_3 - S_2^2 >= 0 and S_4^2 - S_3^3 >= 0 (composed via
    S_3^4 <= S_2^2 S_4^2 <= S_3 S_4^2), the Newton split
    6 e_3 == 1 - 3 S_2 + 2 S_3.  wrong='flip' returns the mutant
    slack S_2^2 - S_3 which must land NEGATIVE (CAUGHT)."""
    q = [_Fr(x) for x in qv]
    n = len(q)
    s1 = sum(q)
    s2 = sum(x * x for x in q)
    s3 = sum(x ** 3 for x in q)
    s4 = sum(x ** 4 for x in q)
    lag1 = sum(q[i] * q[j] * (q[i] - q[j]) ** 2
               for i in range(n) for j in range(n))
    lag2 = sum(q[i] ** 2 * q[j] ** 2 * (q[i] - q[j]) ** 2
               for i in range(n) for j in range(n))
    e3 = sum(q[i] * q[j] * q[k]
             for i in range(n) for j in range(i + 1, n)
             for k in range(j + 1, n))
    slack1 = (s2 * s2 - s3) if wrong == "flip" else (s3 - s2 * s2)
    return dict(S1=s1, S2=s2, S3=s3, S4=s4,
                dev1=lag1 - 2 * (s1 * s3 - s2 * s2),
                dev2=lag2 - 2 * (s2 * s4 - s3 * s3),
                slack1=slack1, slack2=s4 * s4 - s3 ** 3,
                comp_ok=(s3 ** 4 <= s2 * s2 * s4 * s4
                         and s2 * s2 * s4 * s4 <= s3 * s4 * s4),
                newt_dev=6 * e3 - (1 - 3 * s2 + 2 * s3))


def _renyi_bridge(wrong="none"):
    """the r306 bridge with all constants on the equality-tight
    rational witness q = (1/2, 1/4, 1/4), m = 3, rational stand-in
    L = 6/5 for (log m)^2, C = S_3 m^2 / L: S_3 <= C L/m^2 (equal),
    N_3^2 = 1/S_3 >= m^2/(C L) (equal), N_2^2 = 1/S_2^2 >= 1/S_3.
    wrong='reverse' asserts the reversed strict chain (CAUGHT)."""
    q = [_Fr(1, 2), _Fr(1, 4), _Fr(1, 4)]
    m = _Fr(3)
    ell = _Fr(6, 5)
    s2 = sum(x * x for x in q)
    s3 = sum(x ** 3 for x in q)
    cc = s3 * m * m / ell
    if wrong == "reverse":
        return _Fr(1, 1) / (s2 * s2) < m * m / (cc * ell)
    return (s3 <= cc * ell / (m * m)
            and _Fr(1, 1) / s3 >= m * m / (cc * ell)
            and _Fr(1, 1) / (s2 * s2) >= _Fr(1, 1) / s3
            and _Fr(1, 1) / (s2 * s2) >= m * m / (cc * ell))


def _opening_flux(g, factor_mutant=False):
    """the r314 opening-flux lemma: F_1 = g^3 - 3 g g^2 + 2 g^3 is
    IDENTICALLY 0 (cubic algebra); the mutant drops the +2 g^3
    closure term and lands -2 g^3 != 0 for g != 0 (CAUGHT)."""
    if factor_mutant:
        return g ** 3 - 3 * g * (g * g)
    return g ** 3 - 3 * g * (g * g) + 2 * g ** 3


def _flux_telescope(G):
    """the r314 exact flux telescope on one ordered rational block:
    per-edge flux dF = 3 g (s1^2 - s2) of the incoming state; the
    telescoped sum equals the far value x^3 - 3 x Q2 + 2 Q3 exactly
    (returns the deviation, must be the rational 0)."""
    x = sum(G, _Fr(0))
    q2 = sum(g * g for g in G)
    q3 = sum(g ** 3 for g in G)
    s1 = _Fr(0)
    s2 = _Fr(0)
    tel = _Fr(0)
    for i, g in enumerate(G):
        if i > 0:
            tel += 3 * g * (s1 * s1 - s2)
        s1 += g
        s2 += g * g
    return tel - (x ** 3 - 3 * x * q2 + 2 * q3)


def _collision_count(mults, mutant_mult=None):
    """the r314 exact collision counting identity in multiplicity
    power sums: per block with n groups of uniform multiplicity 2,
    3 p_1 p_2 - 2 p_3 == 8 (n + 3 n (n-1)) EXACTLY; mutant_mult
    replaces the uniform multiplicity (mult-1 breaks by the exact
    deficit).  Returns (lhs, rhs) as exact integers."""
    lhs = 0
    rhs = 0
    for block in mults:
        mm = [mutant_mult if mutant_mult is not None else v
              for v in block]
        n = len(mm)
        p1 = sum(mm)
        p2 = sum(v * v for v in mm)
        p3 = sum(v ** 3 for v in mm)
        lhs += 3 * p1 * p2 - 2 * p3
        rhs += 8 * (n + 3 * n * (n - 1))
    return lhs, rhs


