def _frob(a, b):
    """exact Frobenius inner product of two 2x2 rational
    symmetric matrices."""
    return sum(a[i][j] * b[i][j] for i in range(2) for j in range(2))


def _mat_comb(coeffs):
    """exact rational combination sum_i c_i G_i of the mini
    generators."""
    return tuple(tuple(sum(c * g[i][j] for c, g in
                           zip(coeffs, _FARKAS_GENS))
                       for j in range(2)) for i in range(2))


def _pd2(m):
    """exact 2x2 positive-definiteness by leading minors."""
    return m[0][0] > 0 and m[0][0] * m[1][1] - m[0][1] * m[1][0] > 0


