# --------- the ten sealed verdict bars as exact decision logic
def _bar_r306(r, kill_a2=False, a1_holds=False):
    """r306: RENYI3_GO iff zero A=2 violations on all rungs, A=1
    failing on a nonempty witness set (else the sharper form would
    be selected), the A=0 prior rising and the reserve growing."""
    viol_a2 = r["viol_a2"] + (1 if kill_a2 else 0)
    viol_a1 = 0 if a1_holds else r["viol_a1"]
    if viol_a2 > 0:
        return "RENYI3_NO_GO"
    if viol_a1 == 0:
        return "RENYI3_GO(A=1)"
    if r["m3_slope"] > 0 and r["trend"] < 0:
        return "RENYI3_GO(C=1.069, A=2)"
    return "RENYI3_UNDECIDED"


def _bar_r307(r, reserve_mutant=False):
    """r307: FIXED_HEAD_DEAD iff the best fixed-r reserve sits
    under the sealed 1e-2 bar while the FULL flat arch edge
    restores macroscopic reserve on every window and the head
    grows with the window."""
    best = _Fr(2, 100) if reserve_mutant else r["best_fixed"]
    if best >= r["bar"]:
        return "FIXED_HEAD_LIVE"
    if (r["full_min"] > 0 and r["rmin16_cover"] < r["windows"]
            and r["sp_head"] > 0):
        return "HEAD_GROWS + FIXED_HEAD_DEAD"
    return "HEAD_UNDECIDED"


def _bar_r308(r, ctrl_converges=False, break_identity=False):
    """r308: IDENTITY_EXISTS + BLOCK_INDEFINITE_MAIN + FEAS_DIAG
    world separation iff the identity is exact everywhere, the
    sealed min-Frobenius choice is indefinite even on SM0, and the
    feasibility census separates (w9/Twin converge, EPST/SCR
    stall)."""
    dev = _Fr(1, 100) if break_identity else r["w9_dev"]
    if dev > r["bar"]:
        return "NO_IDENTITY"
    epst = _Fr(1, 10 ** 17) if ctrl_converges else r["feas_epst"]
    parts = ["IDENTITY_EXISTS"]
    if r["minfrob_sm0"] < 0:
        parts.append("BLOCK_INDEFINITE_MAIN")
    if (abs(r["feas_w9"]) <= r["feas_tol"]
            and abs(r["feas_twin"]) <= r["feas_tol"]
            and epst < -r["feas_tol"] and r["feas_scr"] < -r["feas_tol"]):
        parts.append("FEAS_DIAG(world separation)")
    return " + ".join(parts)


def _bar_r309(r, cone_breaks=False, b2_full=False):
    """r309: DECOMP_EXACT + MAIN_RESERVE_POSITIVE + CONE_PARTIAL +
    the B1-B4 adjudication: B does NOT overtake A; per reviewer
    case 3 the exact rank-one update identities are FROZEN."""
    viol = r["cone_viol"] + (1 if cone_breaks else 0)
    if viol > 0:
        return "CONE_UNSOUND"
    parts = ["DECOMP_EXACT"]
    if r["res_min_rungs"] > 0 and r["res_min_deg28"] > 0:
        parts.append("MAIN_RESERVE_POSITIVE")
    cert = _Fr(1) if b2_full else r["cert_share"]
    parts.append("CONE_FULL" if cert >= 1 else "CONE_PARTIAL")
    overtake = (r["b1"] and (b2_full or r["b2_full"])
                and r["b3"] and r["b4"])
    parts.append("B_OVERTAKES_A" if overtake
                 else "B_DOES_NOT_OVERTAKE_A(freeze rank-one "
                      "update identities)")
    return " + ".join(parts)


def _bar_r311(r, pd_decompose=False):
    """r311: STRICT_SOURCE_CONE iff the exact in-span rational
    Farkas certificates exist AND no sealed in-span PD sample
    decomposes (membership strictly stronger than positivity),
    with the r308 discriminator DEMARCATED as the budget sign /
    chordal restatement."""
    dec = r["pd_samples"] if pd_decompose else r["pd_decomposable"]
    if dec > 0 or r["exact_certs"] == 0:
        return "CONE_NOT_STRICT"
    if (r["chordal"] and r["ctrl_lmin_epst"] < 0
            and r["ctrl_lmin_scr"] < 0 and r["main_lmin"] > 0):
        return ("STRICT_SOURCE_CONE + R311_DEMARCATION(r308 "
                "discriminator = budget sign / chordal restatement)")
    return "STRICT_SOURCE_CONE"


def _bar_r312(r, offborder=False):
    """r312: COEFFICIENT_SIGN_WALL + LANE_A_CLOSED iff the NNLS
    stall carries a verified Farkas certificate whose mass sits on
    the border/budget row (t-share >= 1/2 and growing with the
    degree) and the exact-grade certificates are strictly
    negative; per the reviewer tree NO GO => Lane A closes as cone
    language with the mechanism NAMED."""
    ts = _Fr(1, 10) if offborder else r["t_share"]
    if r["nnls_stall"] <= 0 or r["yq_sm1"] >= 0 or r["yq_mini"] >= 0:
        return "MEMBERSHIP_OPEN"
    if ts < _Fr(1, 2):
        return "SIGN_WALL_OFF_BORDER(mechanism clause void)"
    return ("COEFFICIENT_SIGN_WALL + LANE_A_CLOSED(mechanism: "
            "block-psd membership without rank-one SDD, obstructed "
            "at the budget/border sign)")


def _bar_r313(r, contracts=False, types_hold=False):
    """r313: BOTH_PARTIAL -- the fork dies/survives at OPPOSITE
    ends: banked fold multiplicity == 2 + real far-triple
    telescope, but TRIPLE_TYPE_MAJORANTS_WRONG (T1/T4 fall on the
    near-critical family) and FLOQUET_EXPANDING (no contraction
    form remains open at chain level)."""
    if r["mult_uniform"] != r["rungs"]:
        return "GENEALOGY_INCOMPLETE"
    tv = 0 if types_hold else r["viol_t1"] + r["viol_t4"]
    sr = _Fr(94, 100) if contracts else r["sr_med"]
    parts = ["BANKED(mult == 2 on %d/%d; TC_far %s)"
             % (r["mult_uniform"], r["rungs"], r["tc_far"])]
    parts.append("COMPOSITION_HOLDS" if tv == 0 and r["viol_t2"] == 0
                 else "TRIPLE_TYPE_MAJORANTS_WRONG")
    parts.append("FLOQUET_CONTRACTS(route reopens)" if sr < 1
                 else "FLOQUET_EXPANDING")
    if tv > 0 and sr >= 1:
        return "BOTH_PARTIAL: " + " + ".join(parts)
    return " + ".join(parts)


def _bar_r314(r, boundary_mutant=False):
    """r314: SIGNED_CUBE_IDENTITY with VANISHING boundary iff the
    Fractions recomposition is the rational 0, the f64 ward holds
    on all rungs, the opening flux F_1 == 0 and the collision
    counting closes on every world."""
    f1 = _Fr(1, 7) if boundary_mutant else r["f1"]
    if r["fr_dev"] != 0 or r["f64_dev"] > r["bar"]:
        return "NO_LOCAL_FLUX_FORM"
    if f1 != 0:
        return "FLUX_WITH_BOUNDARY"
    return ("SIGNED_CUBE_IDENTITY(vanishing boundary; collision "
            "counted exactly on %d/%d worlds)"
            % (r["coll_worlds"], r["coll_worlds"]))


def _bar_r315(r, candidate_survives=False):
    """r315: PHI3_ALL_BLIND iff every presealed candidate carries a
    nonempty violator set (localized on kz55/kz67, the FCIX
    outliers), EPSTEIN holding and the twin band tight."""
    vb = 0 if candidate_survives else r["viol_b"]
    if r["viol_a"] == 0 or vb == 0 or r["viol_c"] == 0:
        return "PHI3_FOUND"
    if (r["epstein_holds"] and r["fcix_out"][0] > r["fcix_med"]
            and r["fcix_out"][1] > r["fcix_med"]):
        return ("PHI3_ALL_BLIND(break localized on kz55+kz67, "
                "FCIX 0.955/0.915 vs med 0.629)")
    return "PHI3_ALL_BLIND"


def _bar_r316(r, kz53_inside=False):
    """r316: TWO_REGIME_DEAD(L fails; H fails) iff kz53 sits above
    the sealed mid-ladder calibration window on the L side (with
    the violator census) and the H constants miss on the one
    testable H rung; the anatomy clause: the obstruction family
    cuts ACROSS the FCIX stratum."""
    rho2 = _Fr(40, 100) if kz53_inside else r["kz53_rho2"]
    l_fails = rho2 > r["win_max"] and r["viol_l"] > 0
    h_fails = (r["h_miss"][0] > 1 and r["h_miss"][1] > 1
               and r["kz55_smallm"])
    if not l_fails and not h_fails:
        return "TWO_REGIME_HOLDS"
    if l_fails and h_fails:
        return ("TWO_REGIME_DEAD(L fails; H fails) + ANATOMY(the "
                "obstruction family cuts across the FCIX stratum: "
                "kz53 at bulk-normal FCIX %s; first-5 load-bearing; "
                "kz55/kz67 near-one-block, TOP1 %s/%s vs %s)"
                % (r["kz53_fcix"], r["top1"][0], r["top1"][1],
                   r["top1_med"]))
    return "TWO_REGIME_SPLIT"


def _four_level(v, b_overtakes=False, r312_go=False,
                two_regime_holds=False):
    """the four-level composition: the day's sealed verdicts
    compose to EXACTLY the reviewer claim split -- (i) the
    architecture adjudication [E], (ii) the rank-one update
    identities [E], (iii) the tensor mechanism [O], (iv) the
    Renyi-3 provenance [O].  The tipping inputs change the
    composition: a passing B2-B4 hands the lane to architecture B,
    a firing r312 GO keeps Lane A open, a surviving two-regime
    bound resolves the provenance question."""
    if b_overtakes:
        lane = "ARCHITECTURE_B_LEADS"
    elif r312_go:
        lane = "LANE_A_OPEN(constructive PSD-G rule fires)"
    else:
        lane = ("LANE_A_CLOSED(cone language, mechanism named) + "
                "LANE_B_NOT_OVERTAKING + LANE_C_PARKED")
    fiber = ("RENYI3_PROVENANCE_RESOLVED" if two_regime_holds else
             "RENYI3_GO_STANDS + PROVENANCE_OPEN(R317 fork: "
             "near-critical family coordinate OR certified "
             "exception family -- reviewer adjudication pending)")
    claims = ("PRIME.LSTAR.ARCHITECTURE_ADJUDICATION.01 [E]; "
              "PRIME.SOURCE.RANKONE.UPDATE.IDENTITY.01 [E]; "
              "PRIME.SOURCE.TENSOR.MECHANISM.01 [O]; "
              "PRIME.L2.RENYI3.PROVENANCE.01 [O]"
              if not (b_overtakes or r312_go or two_regime_holds)
              else "CLAIM_SPLIT_INVALID(recompose)")
    return "%s | %s | %s" % (lane, fiber, claims)


def _architecture_adjudication(gates):
    """the module-own exact section S0: every check appends its
    boolean to gates and prints house-style."""

    def check(name, ok, detail):
        gates.append(bool(ok))
        print("[%s] %s: %s" % ("PASS" if ok else "FAIL", name,
                               detail), flush=True)

    def section(t):
        print("\n--- %s " % t + "-" * max(0, 60 - len(t)), flush=True)

    section("S0-T1 the r306 Hill/Lagrange chain + bridge (exact)")
    toy = _hill_lagrange([_Fr(1, 2), _Fr(1, 4), _Fr(1, 4)])
    uni = _hill_lagrange([_Fr(1, 3)] * 3)
    check("S0-T1a-hill-lagrange",
          toy["dev1"] == 0 and toy["dev2"] == 0
          and toy["S2"] == _Fr(3, 8) and toy["S3"] == _Fr(5, 32)
          and toy["slack1"] == _Fr(1, 64)
          and toy["slack2"] == _Fr(37, 32768) and toy["comp_ok"]
          and toy["newt_dev"] == 0
          and uni["slack1"] == 0 and uni["slack2"] == 0
          and uni["dev1"] == 0 and uni["dev2"] == 0,
          "both Lagrange witnesses dev 0 EXACT on (1/2,1/4,1/4); "
          "slacks 1/64 and 37/32768 EXACT; power-mean chain "
          "composed; Newton split 0; uniform equality case sharp")
    mut = _hill_lagrange([_Fr(1, 2), _Fr(1, 4), _Fr(1, 4)],
                         wrong="flip")
    check("S0-T1b-hill-flip-mutant", mut["slack1"] == _Fr(-1, 64),
          "flipped slack S_2^2 - S_3 = -1/64 NEGATIVE exact -- "
          "the monotonicity direction is live, CAUGHT")
    check("S0-T1c-renyi-bridge",
          _renyi_bridge() and not _renyi_bridge(wrong="reverse"),
          "bridge with all constants exact on the equality-tight "
          "witness (S_3 <= C L/m^2, N_3^2 >= m^2/(C L), N_2^2 >= "
          "1/S_3); reversed-chain mutant CAUGHT -- the r306 leg-A "
          "route N_2 >= N_3 >= m/(sqrt(C) log m) is exact algebra")

    section("S0-T2 the r314 opening-flux lemma + telescope (exact)")
    wit = [_Fr(3, 7), _Fr(-5, 2), _Fr(11, 13), _Fr(0), _Fr(-1, 9)]
    check("S0-T2a-opening-flux",
          all(_opening_flux(g) == 0 for g in wit)
          and _flux_telescope([_Fr(2), _Fr(-1)]) == 0
          and _flux_telescope([_Fr(1), _Fr(-1), _Fr(3, 5)]) == 0
          and _flux_telescope([_Fr(-2, 3), _Fr(7, 4), _Fr(1),
                               _Fr(-5, 6)]) == 0,
          "F_1 == 0 on five rational witnesses (cubic algebra: the "
          "boundary term of the sealed language class VANISHES) "
          "and the edge-flux telescope recomposes the far value "
          "with deviation the rational 0 on three toy blocks")
    check("S0-T2b-flux-factor-mutant",
          _opening_flux(_Fr(3, 7), factor_mutant=True)
          == _Fr(-54, 343)
          and all(_opening_flux(g, factor_mutant=True) != 0
                  for g in wit if g != 0),
          "dropped +2g^3 closure term lands -2g^3 = -54/343 at "
          "g = 3/7 EXACT (nonzero on every nonzero witness) -- "
          "the lemma is not vacuous, CAUGHT")

    section("S0-T3 the r314 collision counting identity (exact)")
    toy_mults = ([2, 2, 2], [2], [2, 2, 2, 2, 2], [2, 2])
    lhs, rhs = _collision_count(toy_mults)
    check("S0-T3a-collision-count", lhs == rhs and lhs == 760,
          "3 p_1 p_2 - 2 p_3 == 8(n + 3n(n-1)) EXACT on four "
          "mult-2 toy blocks (both sides 760; the banked r313 "
          "multiplicity-2 bound makes the collision term exactly "
          "countable)")
    lhs1, rhs1 = _collision_count(toy_mults, mutant_mult=1)
    check("S0-T3b-collision-mult-mutant",
          lhs1 != rhs1 and lhs1 == 95 and rhs1 == 760
          and rhs1 == 8 * lhs1,
          "mult-1 mutant breaks the identity by the exact factor "
          "8 (95 vs 760) -- the identity reads the multiplicity, "
          "CAUGHT")

    section("S0-T4 the r311-class exact Farkas mini-certificate")
    span_ok = (_mat_comb((_Fr(2), _Fr(3), _Fr(-1))) == _FARKAS_Q)
    dual_ok = (all(_frob(_FARKAS_Y, g) >= 0 for g in _FARKAS_GENS)
               and _frob(_FARKAS_Y, _FARKAS_Q) == _Fr(-2))
